local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local HttpService = game:GetService("HttpService")
local AssetService = game:GetService("AssetService")
local player = Players.LocalPlayer
if not player then error("BM Forest must run on the local client") end
local playerGui = player:WaitForChild("PlayerGui", 10)
if not playerGui then error("Enter the game before running BM Forest") end
for _, name in ipairs({"BM_Forest_Local_Viewer_v1", "BM_Forest_Local_Viewer_v2"}) do
    local old = playerGui:FindFirstChild(name)
    if old then
        local signal = old:FindFirstChild("Shutdown")
        if signal and signal:IsA("BindableEvent") then signal:Fire(); task.wait() end
        if old.Parent then old:Destroy() end
    end
end
for _, name in ipairs({"BM_Forest_Local_Scene_v1", "BM_Forest_Local_Scene_v2"}) do
    local old = workspace:FindFirstChild(name)
    if old then old:Destroy() end
end
