local function connect(signal, fn)
    local c = signal:Connect(fn)
    connections[#connections + 1] = c
    return c
end
local function tell(text)
    if not dead and status.Parent then status.Text = text end
end
local function live(id)
    if dead or id ~= job then error("BM_CANCELLED", 0) end
end
local function pause(id) task.wait(); live(id) end
local function keep(obj, id)
    if not obj then error("Editable asset unavailable or memory budget exhausted") end
    if dead or id ~= job then obj:Destroy(); error("BM_CANCELLED", 0) end
    resources[#resources + 1] = obj
    return obj
end
local function vec(t) return Vector3.new(t[1], t[2], t[3]) end
local function character()
    local c = player.Character
    local h = c and c:FindFirstChildOfClass("Humanoid")
    local r = c and c:FindFirstChild("HumanoidRootPart")
    if c and h and r and h.Health > 0 then return c, h, r end
end
local function stopVelocity(root)
    root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
end
local function returnToStart()
    if not travel then return true end
    local record = travel
    local c, h, r = character()
    if not c or c ~= record.character then travel = nil; return true end
    local ok, err = pcall(function()
        stopVelocity(r)
        c:PivotTo(record.pivot)
        stopVelocity(r)
        local camera = workspace.CurrentCamera
        if camera then camera.CameraType = Enum.CameraType.Custom; camera.CameraSubject = h end
    end)
    if not ok then tell("กลับไม่ได้: " .. tostring(err)); return false end
    travel = nil
    return true
end
local function clearScene()
    ready = false
    if scene then scene:Destroy(); scene = nil end
    for i = #resources, 1, -1 do pcall(function() resources[i]:Destroy() end) end
    resources = {}
    appearanceCache = {}
end
local function cleanup()
    if dead then return end
    if not returnToStart() then return end
    dead = true
    SXMedia:PlayEffect(SXMedia.UISounds.window)
    SXSession:Close()
    job = job + 1
    clearScene()
    for _, c in ipairs(connections) do c:Disconnect() end
    connections = {}
    DATA = nil
    if gui.Parent then gui:Destroy() end
end
connect(close.Activated, cleanup)
connect(shutdown.Event, cleanup)
connect(gui.Destroying, cleanup)
connect(player.CharacterAdded, function() travel = nil end)
connect(backButton.Activated, function()
    if not travel then tell("ยังไม่ได้ขึ้นไป หรือเกิดใหม่แล้ว"); return end
    if returnToStart() then tell("กลับจุดเดิมแล้ว") end
end)
local dragInput, dragOrigin, panelOrigin
connect(title.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragInput, dragOrigin, panelOrigin = input, input.Position, panel.Position
    end
end)
connect(UIS.InputChanged, function(input)
    if dragInput and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement) then
        local delta = input.Position - dragOrigin
        local cam = workspace.CurrentCamera
        local size = cam and cam.ViewportSize or Vector2.new(800, 600)
        panel.Position = UDim2.fromOffset(
            math.clamp(panelOrigin.X.Offset + delta.X, 0, math.max(0, size.X - 302)),
            math.clamp(panelOrigin.Y.Offset + delta.Y, 0, math.max(0, size.Y - 290)))
    end
end)
connect(UIS.InputEnded, function(input) if input == dragInput then dragInput = nil end end)

local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local base64values = {}
for i = 1, #alphabet do base64values[string.byte(alphabet, i)] = i - 1 end
local function decodePixels(s, expected, id)
    local bytes = buffer.create(expected)
    local offset = 0
    for i = 1, #s, 4 do
        local a = base64values[string.byte(s, i)]
        local b = base64values[string.byte(s, i + 1)]
        local c = base64values[string.byte(s, i + 2)] or 0
        local d = base64values[string.byte(s, i + 3)] or 0
        if not a or not b then error("Invalid embedded image data") end
        local n = a * 262144 + b * 4096 + c * 64 + d
        for shift = 16, 0, -8 do
            if offset < expected then
                buffer.writeu8(bytes, offset, math.floor(n / (2 ^ shift)) % 256)
                offset = offset + 1
            end
        end
        if i % 32768 == 1 then pause(id) end
    end
    if offset ~= expected then error("Incomplete embedded texture") end
    return bytes
end
local function textureTemplate(name, id)
    if appearanceCache[name] ~= nil then return appearanceCache[name] end
    local image = DATA.images[name]
    local ok, result = pcall(function()
        local editable = keep(AssetService:CreateEditableImage({Size = Vector2.new(image.w, image.h)}), id)
        local pixels = decodePixels(image.rgba, image.w * image.h * 4, id)
        editable:WritePixelsBuffer(Vector2.new(0, 0), Vector2.new(image.w, image.h), pixels)
        local appearance = keep(AssetService:CreateSurfaceAppearanceAsync({
            ColorMap = Content.fromObject(editable)
        }), id)
        appearance.AlphaMode = Enum.AlphaMode.Transparency
        return appearance
    end)
    live(id)
    if not ok then
        appearanceCache[name] = false
        textureFailures = textureFailures + 1
        warn("BM Forest texture " .. name .. ": " .. tostring(result))
        return false
    end
    appearanceCache[name] = result
    texturesLoaded = texturesLoaded + 1
    return result
end
local function build(id)
    local floorCount = 0
    for chunkIndex, chunk in ipairs(DATA.chunks) do
        live(id)
        tell("โหลดรูปทรงจริง " .. chunkIndex .. "/" .. #DATA.chunks)
        local mesh = keep(AssetService:CreateEditableMesh(), id)
        local vids, uids, nids = {}, {}, {}
        for i = 1, #chunk.v, 3 do
            vids[#vids + 1] = mesh:AddVertex(Vector3.new(chunk.v[i], chunk.v[i+1], chunk.v[i+2]) * CONFIG.scale)
            if i % 900 == 1 then pause(id) end
        end
        for i = 1, #chunk.uv, 2 do
            uids[#uids + 1] = mesh:AddUV(Vector2.new(chunk.uv[i], chunk.uv[i+1]))
            if i % 1200 == 1 then pause(id) end
        end
        for i = 1, #chunk.n, 3 do
            nids[#nids + 1] = mesh:AddNormal(Vector3.new(chunk.n[i], chunk.n[i+1], chunk.n[i+2]))
            if i % 900 == 1 then pause(id) end
        end
        for i = 1, #chunk.f, 3 do
            local face = mesh:AddTriangle(vids[chunk.f[i]], vids[chunk.f[i+1]], vids[chunk.f[i+2]])
            mesh:SetFaceUVs(face, {uids[chunk.uf[i]], uids[chunk.uf[i+1]], uids[chunk.uf[i+2]]})
            mesh:SetFaceNormals(face, {nids[chunk.nf[i]], nids[chunk.nf[i+1]], nids[chunk.nf[i+2]]})
            if i % 600 == 1 then pause(id) end
        end
        local isFloor = chunk.name == "Floor"
        local part = keep(AssetService:CreateMeshPartAsync(Content.fromObject(mesh), {
            CollisionFidelity = isFloor and Enum.CollisionFidelity.PreciseConvexDecomposition or Enum.CollisionFidelity.Box,
            RenderFidelity = Enum.RenderFidelity.Precise
        }), id)
        part.Name = chunk.name
        part.Anchored = true
        part.CanCollide = isFloor
        part.CanTouch = false
        part.CanQuery = isFloor
        part.CastShadow = false
        part.DoubleSided = true
        part.Material = Enum.Material.SmoothPlastic
        part.Color = Color3.fromRGB(chunk.color[1], chunk.color[2], chunk.color[3])
        part.CFrame = CFrame.new(origin + vec(chunk.center) * CONFIG.scale)
        if chunk.texture and chunk.texture ~= "" then
            local template = textureTemplate(chunk.texture, id)
            if template then
                local appearance = template:Clone()
                appearance.Parent = part
                part.Color = Color3.new(1, 1, 1)
            end
        end
        part.Parent = scene
        if isFloor then floorCount = floorCount + 1 end
        pause(id)
    end
    if floorCount == 0 then error("No walkable source ground was loaded") end
    -- Invisible backup only; the visible ground is the source mesh.
    local catch = Instance.new("Part")
    catch.Name = "InvisibleCatchFloor"
    catch.Size = Vector3.new(DATA.extent[1] * CONFIG.scale + 30, 2, DATA.extent[3] * CONFIG.scale + 30)
    catch.CFrame = CFrame.new(origin - Vector3.new(0, 12, 0))
    catch.Anchored = true
    catch.Transparency = 1
    catch.CanCollide = true
    catch.CanTouch = false
    catch.Parent = scene
end
connect(loadButton.Activated, function()
    if busy then tell("กำลังโหลดอยู่ครับ"); return end
    if ready then tell("โหลดแล้ว กด UP เพื่อขึ้นไปเดิน"); return end
    local c, h, r = character()
    if not c then tell("รอตัวละครเกิดก่อนครับ"); return end
    busy = true
    job = job + 1
    local id = job
    origin = r.Position + Vector3.new(0, CONFIG.height, 0)
    safeSpawn = origin + vec(DATA.spawn) * CONFIG.scale
    clearScene()
    texturesLoaded, textureFailures = 0, 0
    scene = Instance.new("Model")
    scene.Name = "BM_Forest_Local_Scene_v2"
    task.spawn(function()
        local ok, err = pcall(function() build(id) end)
        if dead or id ~= job then return end
        busy = false
        if not ok then
            clearScene()
            local msg = tostring(err)
            warn("BM Forest ORIGINAL load failed: " .. msg)
            tell("โหลดโมเดลจริงไม่ได้: " .. string.sub(msg, 1, 115))
            detail.Text = "อาจติดสิทธิ์ Mesh API หรือหน่วยความจำ ดู Console"
            return
        end
        scene.Parent = workspace
        ready = true
        tell("รูปทรงเดิมครบ 36,702 สามเหลี่ยม • กด UP")
        detail.Text = "Texture โหลด " .. texturesLoaded .. "/5 • ไฟล์ใบไม้ขาด 2 ภาพ"
        if textureFailures > 0 then detail.Text = SXMedia:SourceText(detail) .. " • บางภาพโหลดไม่ได้" end
    end)
end)
connect(upButton.Activated, function()
    if not ready then tell("ต้องโหลดโมเดลจริงให้สำเร็จก่อนขึ้นไป"); return end
    local c, h, r = character()
    if not c then tell("รอตัวละครเกิดก่อนครับ"); return end
    if h.SeatPart or h.Sit then tell("ออกจากที่นั่งก่อนขึ้นไปครับ"); return end
    if not travel then travel = {character = c, pivot = c:GetPivot()} end
    local record = travel
    local ok, err = pcall(function()
        stopVelocity(r)
        c:PivotTo(CFrame.new(safeSpawn + Vector3.new(0, math.max(5, h.HipHeight + r.Size.Y / 2 + 2), 0)))
        stopVelocity(r)
        local camera = workspace.CurrentCamera
        if camera then camera.CameraType = Enum.CameraType.Custom; camera.CameraSubject = h end
    end)
    if not ok then tell("ย้ายตัวละครไม่ได้: " .. tostring(err)); return end
    tell("ขึ้นไปแล้ว ใช้ปุ่มเดินตามปกติ • BACK เพื่อกลับ")
    task.delay(3, function()
        if dead or travel ~= record then return end
        local current, _, root = character()
        if current == record.character and root and math.abs(root.Position.Y - origin.Y) > 250 then
            travel = nil
            tell("เกมย้ายตัวกลับหรือออกจากป่าแล้ว ไม่มีการย้ายซ้ำ")
        end
    end)
end)
local elapsed = 0
connect(RunService.Heartbeat, function(dt)
    if not travel or not ready then return end
    elapsed = elapsed + dt
    if elapsed < 0.3 then return end
    elapsed = 0
    local c, _, r = character()
    if not c or c ~= travel.character then travel = nil; return end
    if r.Position.Y < origin.Y - 150 then
        travel = nil
        tell("ออกจากพื้นที่ป่าแล้ว เกมอาจย้ายตัวกลับ")
    elseif r.Position.Y < origin.Y - 8 then
        if returnToStart() then tell("กลับจุดเดิมแล้ว เพราะหลุดจากพื้นป่า") end
    end
end)
warn("BM Forest: source MTL textures absent from ZIP: " .. table.concat(DATA.missing, ", "))

SXSession:Bind(gui)
SXSession:Finish()
